// 按照运行时间进行降序排序
bool cmp(pair<int, int> a, pair<int, int> b) {
    return a.second > b.second;
}
​
​
int getMinTime(vector<pair<int, int>> ans) {
    int res = 0;
    // 贪心 优先让执行时间长的任务先配置
    sort(ans.begin(), ans.end(), cmp);
​
​
    // 记录上个任务配置完后的时间
    int lastConfigEndTime = 0;
    for (int i = 0; i < ans.size(); i++) {
        int configTime = ans[i].first;
        int runTime = ans[i].second;
        lastConfigEndTime += configTime;
        // 获取最大执行结束时间
        res = max(res, lastConfigEndTime + runTime);
    }
​
    return res;
}
​
​
int main() {
    int m;
    cin >> m;
​
    for (int i = 0; i < m; i++) {
        int n;
        cin >> n;
        vector<pair<int, int>> ans(n);
        for (int j = 0; j < n; j++) {
            int b, a;
            cin >> b >> a;
            ans[j] = {b, a};
        }
​
        int res = getMinTime(ans);
        cout << res << endl;
    }
    return 0;
}

