import java.util.*;
​
public class Main {
​
    // 按照运行时间降序排序
    static class Task {
        int configTime, runTime;
        Task(int configTime, int runTime) {
            this.configTime = configTime;
            this.runTime = runTime;
        }
    }
​
    public static int getMinTime(List<Task> tasks) {
        // 贪心策略，运行时间长的任务先执行
        tasks.sort((a, b) -> b.runTime - a.runTime);
​
        int res = 0;
        int lastConfigEndTime = 0;
        for (Task task : tasks) {
            lastConfigEndTime += task.configTime;
            res = Math.max(res, lastConfigEndTime + task.runTime);
        }
​
        return res;
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt(); // 测试组数
​
        for (int i = 0; i < m; i++) {
            int n = sc.nextInt(); // 每组任务数
            List<Task> tasks = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                int b = sc.nextInt(); // 配置时间
                int a = sc.nextInt(); // 运行时间
                tasks.add(new Task(b, a));
            }
            int res = getMinTime(tasks);
            System.out.println(res);
        }
    }
}
