package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
type Task struct {
    configTime int
    runTime    int
}
​
func getMinTime(tasks []Task) int {
    // 贪心：运行时间长的优先
    sort.Slice(tasks, func(i, j int) bool {
        return tasks[i].runTime > tasks[j].runTime
    })
​
    res := 0
    lastConfigEndTime := 0
    for _, task := range tasks {
        lastConfigEndTime += task.configTime
        if lastConfigEndTime+task.runTime > res {
            res = lastConfigEndTime + task.runTime
        }
    }
    return res
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    m, _ := strconv.Atoi(strings.TrimSpace(line))
​
    for i := 0; i < m; i++ {
        line, _ = reader.ReadString('\n')
        n, _ := strconv.Atoi(strings.TrimSpace(line))
​
        tasks := make([]Task, n)
        for j := 0; j < n; j++ {
            line, _ = reader.ReadString('\n')
            parts := strings.Fields(line)
            b, _ := strconv.Atoi(parts[0])
            a, _ := strconv.Atoi(parts[1])
            tasks[j] = Task{configTime: b, runTime: a}
        }
​
        res := getMinTime(tasks)
        fmt.Println(res)
    }
}
